@dataclass(frozen=True)
class Req:
    code: str | None
    text: str  # the requirement as printed; "<br/>" marks a forced line end, "|" a page break inside it
    parents: tuple[str, ...] = ()
    note: str | None = None  # a Note inside the requirement column, before the trace
    full_note: str | None = None  # a full-width Note after the trace
    items: tuple[str, ...] = ()  # list items printed under the requirement text
    marker: str = "\u2013"  # a dash bullet ("•" in the standard PDF fonts extracts as "(cid:127)"), or "" for lettered items
    items_break_after: int | None = None  # a page break inside the list, after this many items
    parents_break_after: int | None = None  # a page break inside the trace, after this many parent codes

    @property
    def plain(self) -> str:
        return " ".join(self.text.replace("<br/>", "").replace("|", " ").replace("<i>", "").replace("</i>", "").split())


@dataclass(frozen=True)
class Section:
    number: str
    title: str
    kind: str  # "context" | "front" | "feature" | "empty" | "back"
    reqs: tuple[Req, ...] = ()
    prose: tuple[str, ...] = ()  # descriptive sentences (context), or the one-line body of an empty section
    break_before: bool = False


def _spread(first: int, last: int, n: int) -> list[int]:
    return [round(first + i * (last - first) / (n - 1)) for i in range(n)] if n > 1 else [first]


_OBJECTS = [
    "vent actuator", "heating loop", "humidity sensor", "irrigation valve", "shade screen", "CO2 doser", "mist nozzle bank",
    "circulation fan", "thermal curtain", "light bar", "drain pump", "soil probe", "roof window", "nutrient mixer", "boiler interface",
    "frost guard", "door contact", "rain detector", "wind vane", "condensate tray",
]
_VERBS = [
    "report its position to the controller", "stop within the configured travel limit", "return to the safe state on loss of supply",
    "log every change of set point", "accept a new set point without a restart", "keep its last value after a power cycle",
    "signal a fault on the local panel", "complete a full cycle", "resume the previous program after a reset",
    "limit its output to the configured maximum",
]
_LIMITS = ["within {n} s", "at least every {n} min", "for no less than {n} h", "within {n} % of the set point", "at up to {n} cycles per day"]


def _sentence(seed: int, subject: str | None = None) -> str:
    obj = subject or _OBJECTS[seed % len(_OBJECTS)]
    verb = _VERBS[(seed // len(_OBJECTS) + seed) % len(_VERBS)]
    limit = _LIMITS[seed % len(_LIMITS)].format(n=3 + (seed * 7) % 90)
    return f"The {obj} shall {verb} {limit}."


def _parents(seed: int) -> tuple[str, ...]:
    shapes = [f"GCS_{seed % 9 + 1}", f"SYS_{10 + seed % 80}", f"CLIMAT_{100 + seed % 900}", f"SYS_{10 + seed % 80}.{seed % 4 + 1}"]
    return tuple(shapes[: 1 + seed % 2]) if seed % 3 else (shapes[2], shapes[3])


def _reqs(prefix: str, numbers: list[int], start_seed: int, **special: Req) -> tuple[Req, ...]:
    out = []
    for i, n in enumerate(numbers):
        code = f"{prefix}_{n}"
        out.append(special.get(code) or Req(code, _sentence(start_seed + i), _parents(start_seed + i)))
    return tuple(out)


